function sweepProfile(curve, profile, samples = 80, closed = true) {
  const pos = [], nrm = [], along = [], idx = [];
  const up = new Vector3(0, 1, 0), T = new Vector3(), Rv = new Vector3(), U = new Vector3(), Pt = new Vector3();
  const nE = closed ? profile.length : profile.length - 1;
  const frames = [];
  for (let i = 0; i <= samples; i++) {
    const t = i / samples;
    curve.getPointAt(t, Pt);
    curve.getTangentAt(t, T);
    Rv.crossVectors(T, up).normalize();
    U.crossVectors(Rv, T).normalize();
    frames.push([Pt.clone(), Rv.clone(), U.clone()]);
  }
  for (let e3 = 0; e3 < nE; e3++) {
    const [u0, v0] = profile[e3], [u1, v1] = profile[(e3 + 1) % profile.length];
    const du = u1 - u0, dv = v1 - v0, l = Math.hypot(du, dv);
    const nu = dv / l, nv = -du / l;
    const base = pos.length / 3;
    for (let i = 0; i <= samples; i++) {
      const [P0, R0, U0] = frames[i];
      for (const [u, v2] of [[u0, v0], [u1, v1]]) {
        pos.push(P0.x + R0.x * u + U0.x * v2, P0.y + R0.y * u + U0.y * v2, P0.z + R0.z * u + U0.z * v2);
        nrm.push(R0.x * nu + U0.x * nv, R0.y * nu + U0.y * nv, R0.z * nu + U0.z * nv);
        along.push(i / samples);
      }
    }
    for (let i = 0; i < samples; i++) {
      const a2 = base + i * 2;
      idx.push(a2, a2 + 2, a2 + 1, a2 + 1, a2 + 2, a2 + 3);
    }
  }
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(pos, 3));
  g.setAttribute("normal", new Float32BufferAttribute(nrm, 3));
  g.setAttribute("along", new Float32BufferAttribute(along, 1));
  g.setIndex(idx);
  return g;
}
